import json
with open('session.v4.jsonl') as f:
    lines=[json.loads(l) for l in f]
from collections import Counter
print(Counter(l.get('type') for l in lines))
# print all assistant messages text and tool calls briefly
for i,l in enumerate(lines):
    t=l.get('type')
    if t=='assistant/message':
        c=l['data'].get('content') or l['data'].get('message',{}).get('content')
        if isinstance(c,list):
            for b in c:
                if b.get('type')=='text' and b.get('text','').strip():
                    print(i,'ASSIST:', b['text'][:500].replace(chr(10),' | '))
                elif b.get('type')=='tool_use':
                    print(i,'TOOLCALL:', b.get('name'), json.dumps(b.get('input'))[:300])
        else:
            print(i,'ASSIST-raw', str(c)[:300])
" > assistant_log.txt; wc -l assistant_log.txt; head -80 assistant_log.txt", "description": "Summarize assistant messages and tool calls"}

