/**
 * Entire toolkit — a Host-only DSH bundle.
 *
 * The plugin gives the model a typed, gated view of the Entire CLI: sessions,
 * checkpoints, search, code history, trails, reviews, the code graph, and a
 * classified passthrough for the remaining commands and the authenticated API.
 *
 * Reads never prompt. Repository-scoped mutations require `allowWrites`;
 * machine/account/control-plane calls require `allowAdmin`. Gated calls ask
 * through the Harness approval pipeline, so an approval-free deployment denies
 * them instead of silently writing.
 */

import { createSessionBridge } from './lib/bridge.js';
import { resolveConfig } from './lib/config.js';
import { buildInvocation } from './lib/commands.js';
import { EntireError, resolveCwd, runEntireCommand } from './lib/exec.js';
import { TOOL_NAMES, describeCall, permissionFor, policyForCall } from './lib/policy.js';
import { formatResult } from './lib/text.js';
import { createTools } from './lib/tools.js';

export const inject = ['tools'];

const PROMPT_TEXT =
  'Entire records agent sessions as checkpoints linked to commits. Before rewriting unfamiliar code, use entire_history (why/blame/experts) and entire_search to recover intent; use entire_sessions and entire_checkpoints to inspect prior work. ' +
  'This plugin reads Entire’s data and, where a repository carries .entire/dsh-hooks.json, forwards DSH session events to `entire hooks dsh` so DSH sessions become Entire sessions and checkpoints.';

function argumentRecord(value) {
  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);
      return parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch {
      return {};
    }
  }
  return value !== null && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

export function apply(ctx, rawConfig) {
  const settings = resolveConfig(rawConfig);
  const activeRuns = new Set();
  const disposers = [];

  const invoke = async (tool, args, exec) => {
    const input = argumentRecord(args);
    const invocation = buildInvocation(tool, input.action, input, settings);
    const cwd = await resolveCwd(ctx, exec?.agent, exec?.signal, settings);

    const controller = new AbortController();
    const forwardAbort = () => controller.abort('tool call cancelled');
    if (exec?.signal !== undefined) {
      if (exec.signal.aborted === true) controller.abort('tool call cancelled');
      else exec.signal.addEventListener('abort', forwardAbort, { once: true });
    }

    activeRuns.add(controller);
    try {
      const result = await runEntireCommand({
        binary: settings.binary,
        args: invocation.args,
        cwd,
        timeoutMs: invocation.timeoutMs,
        signal: controller.signal,
        stdin: invocation.stdin
      });
      return formatResult(result, settings.maxOutputChars);
    } catch (error) {
      if (error instanceof EntireError) throw new Error(error.message);
      throw error;
    } finally {
      activeRuns.delete(controller);
      if (exec?.signal !== undefined) {
        exec.signal.removeEventListener('abort', forwardAbort);
      }
    }
  };

  for (const definition of createTools(invoke)) {
    disposers.push(ctx.tools.register(definition));
  }

  disposers.push(
    ctx.on('tools/pre-execute', async (exec, next) => {
      const decision = await next();
      if (!TOOL_NAMES.includes(exec.name)) return decision;
      if (decision.kind !== 'allow') return decision;

      const args = argumentRecord(exec.arguments);
      const policy = policyForCall(exec.name, args);
      const verdict = permissionFor(policy, settings, describeCall(exec.name, args));

      if (verdict.kind === 'deny') {
        return {
          kind: 'deny',
          reason: verdict.reason,
          info: { name: 'EntirePolicy', code: 'ENTIRE_PERMISSION_DENIED' }
        };
      }
      if (verdict.kind === 'ask') {
        return { kind: 'ask', reason: verdict.reason };
      }
      return decision;
    })
  );

  if (settings.capture) {
    const bridge = createSessionBridge(ctx, settings);
    disposers.push(() => bridge.dispose());
  }

  if (settings.promptSection) {
    const systemPrompt = ctx.get('systemPrompt');
    if (systemPrompt !== undefined) {
      disposers.push(
        systemPrompt.section({
          name: 'entire',
          order: 2470,
          text: ({ scope }) =>
            ctx.tools.get('entire_status', scope) === undefined ? '' : PROMPT_TEXT
        })
      );
    }
  }

  disposers.push(
    ctx.on('dispose', () => {
      for (const controller of activeRuns) {
        try {
          controller.abort('plugin unloaded');
        } catch {
          // Best effort; the child close handler owns the outcome.
        }
      }
      activeRuns.clear();
    })
  );

  return () => {
    for (const dispose of disposers) {
      try {
        dispose();
      } catch {
        // Teardown must not mask the first failure with a later one.
      }
    }
  };
}

/**
 * Entry point: dispatch one protocol subcommand per process invocation.
 * Each invocation is stateless; the CLI calls us again for every step.
 */
import { dispatch } from './protocol.js';
import { createDshAgent } from './dsh/agent.js';

export async function main(argv) {
  try {
    return await dispatch(createDshAgent(), argv);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write('entire-agent-dsh: ' + message + '\n');
    return 1;
  }
}
=== protocol.js
/**
 * Entire Agent Integration Protocol: subcommand dispatch.
 *
 * Every subcommand reads/writes JSON on stdin/stdout (raw bytes where the
 * protocol says so), is stateless, and reports failures as a nonzero exit code
 * with a message on stderr.
 *
 * Command list and shapes: https://docs.entire.com/agents/agent-integration-protocol/commands
 */
import process from 'node:process';

const MAX_CHUNK_SIZE = 4 * 1024 * 1024;

export function writeJson(value) {
  process.stdout.write(JSON.stringify(value) + '\n');
}

export async function readStdin() {
  const chunks = [];
  for await (const chunk of process.stdin) chunks.push(chunk);
  return Buffer.concat(chunks);
}

async function readJsonStdin() {
  const raw = await readStdin();
  const text = raw.toString('utf8').trim();
  if (text === '') throw new Error('expected a JSON payload on stdin');
  return JSON.parse(text);
}

export function parseFlags(argv, options = {}) {
  const booleanFlags = options.boolean ?? [];
  const flags = {};
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (!arg.startsWith('--')) continue;
    const eq = arg.indexOf('=');
    if (eq !== -1) {
      flags[arg.slice(2, eq)] = arg.slice(eq + 1);
      continue;
    }
    const key = arg.slice(2);
    if (booleanFlags.includes(key)) {
      flags[key] = true;
      continue;
    }
    const next = argv[i + 1];
    if (next === undefined || next.startsWith('--')) {
      flags[key] = true;
      continue;
    }
    flags[key] = next;
    i += 1;
  }
  return flags;
}

export function intFlag(value, fallback) {
  const parsed = Number.parseInt(String(value ?? ''), 10);
  return Number.isFinite(parsed) ? parsed : fallback;
}

export async function dispatch(agent, argv) {
  const [command, ...rest] = argv;
  switch (command) {
    case 'info':
      writeJson(agent.info());
      return 0;
    case 'detect':
      writeJson(agent.detect());
      return 0;
    case 'get-session-id': {
      const input = await readJsonStdin();
      writeJson({ session_id: agent.getSessionID(input) });
      return 0;
    }
    case 'get-session-dir': {
      const flags = parseFlags(rest);
      writeJson({ session_dir: agent.getSessionDir(flags['repo-path']) });
      return 0;
    }
    case 'resolve-session-file': {
      const flags = parseFlags(rest);
      writeJson({ session_file: agent.resolveSessionFile(flags['session-dir'], flags['session-id']) });
      return 0;
    }
    case 'read-session': {
      const input = await readJsonStdin();
      writeJson(agent.readSession(input));
      return 0;
    }
    case 'write-session': {
      const session = await readJsonStdin();
      agent.writeSession(session);
      return 0;
    }
    case 'read-transcript': {
      const flags = parseFlags(rest);
      const bytes = agent.readTranscript(flags['session-ref']);
      process.stdout.write(bytes);
      return 0;
    }
    case 'chunk-transcript': {
      const flags = parseFlags(rest);
      const bytes = await readStdin();
      writeJson({ chunks: agent.chunkTranscript(bytes, intFlag(flags['max-size'], MAX_CHUNK_SIZE)) });
      return 0;
    }
    case 'reassemble-transcript': {
      const input = await readJsonStdin();
      process.stdout.write(agent.reassembleTranscript(input.chunks ?? []));
      return 0;
    }
    case 'format-resume-command': {
      const flags = parseFlags(rest);
      writeJson({ command: agent.formatResumeCommand(flags['session-id']) });
      return 0;
    }
    case 'parse-hook': {
      const flags = parseFlags(rest);
      const payload = await readStdin();
      const event = agent.parseHook(flags.hook, payload);
      if (event === null || event === undefined) {
        process.stdout.write('null\n');
        return 0;
      }
      writeJson(event);
      return 0;
    }
    case 'install-hooks': {
      const flags = parseFlags(rest, { boolean: ['local-dev', 'force'] });
      const installed = agent.installHooks({
        localDev: flags['local-dev'] === true,
        force: flags.force === true
      });
      writeJson({ hooks_installed: installed });
      return 0;
    }
    case 'uninstall-hooks':
      agent.uninstallHooks();
      return 0;
    case 'are-hooks-installed':
      writeJson({ installed: agent.areHooksInstalled() });
      return 0;
    case 'get-transcript-position': {
      const flags = parseFlags(rest);
      writeJson({ position: agent.getTranscriptPosition(flags.path) });
      return 0;
    }
    case 'extract-modified-files': {
      const flags = parseFlags(rest);
      const result = agent.extractModifiedFiles(flags.path, intFlag(flags.offset, 0));
      writeJson({ files: result.files, current_position: result.currentPosition });
      return 0;
    }
    case 'extract-prompts': {
      const flags = parseFlags(rest);
      writeJson({ prompts: agent.extractPrompts(flags['session-ref'], intFlag(flags.offset, 0)) });
      return 0;
    }
    case 'extract-summary': {
      const flags = parseFlags(rest);
      const result = agent.extractSummary(flags['session-ref']);
      writeJson({ summary: result.summary, has_summary: result.hasSummary });
      return 0;
    }
    case 'calculate-tokens': {
