    uninstallHooks: () => uninstallHooks(),
    areHooksInstalled: () => areHooksInstalled(),

    getTranscriptPosition: (sessionRef) => transcript.transcriptPosition(sessionRef),

    extractModifiedFiles: (sessionRef, offset) => transcript.extractModifiedFiles(sessionRef, offset),
    extractPrompts: (sessionRef, offset) => transcript.extractPrompts(sessionRef, offset),
    extractSummary: (sessionRef) => transcript.extractSummary(sessionRef),
    calculateTokens: (bytes, offset) => transcript.calculateTokens(bytes, offset)
