/**
 * Hook installation for DSH.
 *
 * Unlike Claude Code or Amp, DSH has no per-repository hook file: its plugin
 * surface is profile-scoped (a plugin is added to a DSH profile, not to a repo).
 * So install-hooks writes a repository marker instead, and the bridge plugin
 * (installed once per DSH profile) activates only in repositories that carry
 * the marker.
 *
 * The contract the CLI cares about is the exit status and the JSON count.
 */
import fs from 'node:fs';
import path from 'node:path';
import { HOOK_NAMES } from './info.js';

export const MARKER_RELATIVE_PATH = path.join('.entire', 'dsh-hooks.json');
export const BRIDGE_PACKAGE = '@sredevopsorg/dsh-entire-bridge';

export function repoRoot() {
  return process.env.ENTIRE_REPO_ROOT ?? process.cwd();
}

export function markerPath(root = repoRoot()) {
  return path.join(root, MARKER_RELATIVE_PATH);
}

export function installHooks(options = {}) {
  const root = repoRoot();
  const marker = markerPath(root);
  if (!options.force && fs.existsSync(marker)) return 0;
  fs.mkdirSync(path.dirname(marker), { recursive: true });
  const record = {
    version: 1,
    agent: 'dsh',
    bridge: BRIDGE_PACKAGE,
    hook_names: HOOK_NAMES,
    installed_at: new Date().toISOString(),
    local_dev: options.localDev === true
  };
  fs.writeFileSync(marker, JSON.stringify(record, null, 2) + '\n');
  return HOOK_NAMES.length;
}

export function uninstallHooks() {
  const marker = markerPath();
  try {
    fs.unlinkSync(marker);
  } catch (error) {
    if (error?.code !== 'ENOENT') throw error;
  }
}

export function areHooksInstalled() {
  return fs.existsSync(markerPath());
}

/**
 * DSH session storage discovery.
 *
 * Sessions live under DSH_SESSIONS_DIR or ~/.dsh/sessions, one directory per
 * workspace slug, one directory per session id:
 *   <root>/<slug>/<session-id>/session.v4.jsonl.zstd
 *
 * The slug encodes the workspace path with slashes replaced by dashes and the
 * whole value wrapped in double dashes, e.g.
 *   /home/me/project -> --home-me-project--
 * Slugs are an implementation detail, so a lookup that misses falls back to
 * scanning session headers for the matching cwd.
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { decodeSessionBytes } from './transcript.js';

const SESSION_FILE_NAMES = ['session.v4.jsonl.zstd', 'session.v4.jsonl', 'session.jsonl', 'session.json'];

export function sessionsRoot() {
  return process.env.DSH_SESSIONS_DIR ?? path.join(os.homedir(), '.dsh', 'sessions');
}

export function stateDir() {
  return process.env.DSH_ENTIRE_STATE_DIR ?? path.join(os.homedir(), '.dsh', 'entire', 'sessions');
}

export function slugForWorkspace(repoPath) {
  const absolute = path.resolve(repoPath).replace(/[\\/]+$/, '');
  const encoded = absolute.replace(/[\\/]/g, '-').replace(/^-+/, '');
  return '--' + encoded + '--';
}

function isDirectory(candidate) {
  try {
    return fs.statSync(candidate).isDirectory();
  } catch {
    return false;
  }
}

export function readSessionHeader(sessionFile) {
  try {
    const bytes = decodeSessionBytes(fs.readFileSync(sessionFile));
    const firstLine = bytes.toString('utf8').split('\n', 1)[0];
    const parsed = JSON.parse(firstLine);
    return parsed !== null && typeof parsed === 'object' ? parsed : null;
  } catch {
    return null;
  }
}

function firstSessionFile(sessionDir) {
  for (const name of SESSION_FILE_NAMES) {
    const candidate = path.join(sessionDir, name);
    if (fs.existsSync(candidate)) return candidate;
  }
  return null;
}

export function findSessionDir(repoPath) {
  const repo = path.resolve(repoPath || process.env.ENTIRE_REPO_ROOT || process.cwd());
  const root = sessionsRoot();
  const direct = path.join(root, slugForWorkspace(repo));
  if (isDirectory(direct)) return direct;

  if (!isDirectory(root)) {
    throw new Error('DSH session root not found: ' + root);
  }
  for (const entry of fs.readdirSync(root)) {
    const workspaceDir = path.join(root, entry);
    if (!isDirectory(workspaceDir)) continue;
    for (const sessionId of fs.readdirSync(workspaceDir)) {
      const sessionDir = path.join(workspaceDir, sessionId);
      if (!isDirectory(sessionDir)) continue;
      const file = firstSessionFile(sessionDir);
      if (file === null) continue;
      const header = readSessionHeader(file);
      if (header !== null && header.cwd === repo) return workspaceDir;
    }
  }
  throw new Error('no DSH session directory for workspace: ' + repo);
}

export function resolveSessionFile(sessionDir, sessionId) {
  if (!sessionDir) throw new Error('--session-dir is required');
  if (!sessionId) throw new Error('--session-id is required');
  const sessionDirPath = path.join(sessionDir, sessionId);
  for (const name of SESSION_FILE_NAMES) {
    const candidate = path.join(sessionDirPath, name);
    if (fs.existsSync(candidate)) return candidate;
  }
  throw new Error('no session file for session ' + sessionId + ' under ' + sessionDir);
}

export function sessionFileFor(sessionId, repoPath) {
  return resolveSessionFile(findSessionDir(repoPath), sessionId);
}
