/**
 * Normalize the DSH bridge's hook payload into an Entire lifecycle Event.
 *
 * The bridge plugin (bridge/index.js) subscribes to the DSH host's
 * session/created, session/event and session/disposed events and shells out to
 * `entire hooks dsh <hook>`, which calls us back with
 * `parse-hook --hook <hook>` and the raw payload on stdin.
 *
 * Payload contract (bridge-owned):
 *   { hook_type, session_id, session_ref, timestamp, user_prompt?,
 *     tool_name?, tool_use_id?, tool_input?, raw_data: { dsh: {...} } }
 *
 * Event types: 1 SessionStart, 2 TurnStart, 3 TurnEnd, 4 Compaction,
 *              5 SessionEnd, 6 SubagentStart, 7 SubagentEnd.
 */
const HOOK_EVENT_TYPES = {
  'session-start': 1,
  'turn-start': 2,
  'turn-end': 3,
  compaction: 4,
  'session-end': 5,
  'subagent-start': 6,
  'subagent-end': 7
};

export function parseDshHook(hookName, input) {
  const type = HOOK_EVENT_TYPES[hookName];
  if (type === undefined) return null;

  let payload = null;
  try {
    payload = JSON.parse(Buffer.isBuffer(input) ? input.toString('utf8') : String(input));
