  if (payload === null || typeof payload !== 'object') return null;

  const sessionId = payload.session_id;
  if (typeof sessionId !== 'string' || sessionId === '') return null;

  const raw = payload.raw_data?.dsh ?? {};
  const event = {
    type,
    session_id: sessionId,
    timestamp: typeof payload.timestamp === 'string' && payload.timestamp !== '' ? payload.timestamp : new Date().toISOString()
  };
  if (typeof payload.session_ref === 'string' && payload.session_ref !== '') {
    event.session_ref = payload.session_ref;
  }
  if (typeof payload.user_prompt === 'string' && payload.user_prompt !== '') {
    event.prompt = payload.user_prompt;
  }
  if (typeof raw.model === 'string' && raw.model !== '') {
    event.model = raw.model;
  }
  if (typeof payload.tool_use_id === 'string' && payload.tool_use_id !== '') {
    event.tool_use_id = payload.tool_use_id;
  }
  if (payload.tool_input !== undefined) {
    event.tool_input = payload.tool_input;
  }
  if (type === 6 || type === 7) {
    if (typeof raw.subagent_id === 'string' && raw.subagent_id !== '') event.subagent_id = raw.subagent_id;
    if (typeof raw.subagent_type === 'string' && raw.subagent_type !== '') event.subagent_type = raw.subagent_type;
