import fs from 'node:fs';
import zlib from 'node:zlib';

const ZSTD_MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
const PREPARED_SUFFIX = '.entire.jsonl';
const PATH_KEYS = ['file_path', 'filePath', 'path', 'notebook_path', 'target_file', 'absolute_path'];
const HUMAN_SOURCE_KINDS = new Set(['human', 'user', 'prompt']);

export function decodeSessionBytes(input) {
  const bytes = Buffer.isBuffer(input) ? input : Buffer.from(input);
  if (bytes.length >= 4 && bytes.subarray(0, 4).equals(ZSTD_MAGIC)) {
    return zlib.zstdDecompressSync(bytes);
  }
