}

export function parseTranscript(input) {
  const text = decodeSessionBytes(input).toString('utf8');
  const events = [];
  let header = null;
  for (const line of text.split('\n')) {
    const trimmed = line.trim();
    if (trimmed === '') continue;
    let event;
    try {
      event = JSON.parse(trimmed);
    } catch {
      continue;
    }
    if (event === null || typeof event !== 'object') continue;
    if (header === null && event.type === 'session') {
      header = event;
      continue;
    }
    events.push(event);
  }
  return { header, events };
}

export function preparedTranscriptPath(sessionRef) {
  return sessionRef + PREPARED_SUFFIX;
}

export function readTranscriptBytes(sessionRef) {
  if (!sessionRef) throw new Error('session reference is required');
  const prepared = preparedTranscriptPath(sessionRef);
  if (fs.existsSync(prepared)) return fs.readFileSync(prepared);
  if (!fs.existsSync(sessionRef)) throw new Error('session transcript not found: ' + sessionRef);
  return decodeSessionBytes(fs.readFileSync(sessionRef));
}

export function prepareTranscript(sessionRef) {
  if (!sessionRef) throw new Error('session reference is required');
