  for (const event of events) {
    if (event.type !== 'assistant/message') continue;
    const reported = event.data?.usage;
    if (reported === null || typeof reported !== 'object') continue;
    usage.input_tokens += reported.inputTokens ?? 0;
    usage.output_tokens += reported.outputTokens ?? 0;
    usage.cache_creation_tokens += reported.cacheWriteTokens ?? 0;
    usage.cache_read_tokens += reported.cacheReadTokens ?? 0;
    usage.api_call_count += 1;
  }
  return usage;
}

export function latestModel(events) {
  let model = '';
  for (const event of events) {
    if (event.type !== 'assistant/message') continue;
    const candidate = event.data?.source?.model;
    if (typeof candidate === 'string' && candidate !== '') model = candidate;
  }
