}

export function sessionTitle(events) {
  for (const event of events) {
    if (event.type !== 'session/title') continue;
    const title = event.data?.title;
    if (typeof title === 'string' && title !== '') return title;
  }
  return null;
}

export function extractModifiedFiles(sessionRef, offset) {
  const bytes = readTranscriptBytes(sessionRef);
  const slice = bytes.subarray(Math.max(0, Math.min(offset, bytes.length)));
  const { events } = parseTranscript(slice);
  return { files: modifiedFiles(events), currentPosition: bytes.length };
}

export function extractPrompts(sessionRef, offset) {
  const bytes = readTranscriptBytes(sessionRef);
  const slice = bytes.subarray(Math.max(0, Math.min(offset, bytes.length)));
  return humanPrompts(parseTranscript(slice).events);
}

export function extractSummary(sessionRef) {
  const bytes = readTranscriptBytes(sessionRef);
  const { events } = parseTranscript(bytes);
  const title = sessionTitle(events);
  if (title !== null) return { summary: title, hasSummary: true };
  const [first] = humanPrompts(events);
  if (first === undefined) return { summary: '', hasSummary: false };
  return { summary: first.slice(0, 500), hasSummary: true };
}

export function calculateTokens(input, offset) {
  const bytes = decodeSessionBytes(input);
  const slice = bytes.subarray(Math.max(0, Math.min(offset, bytes.length)));
  return tokenUsage(parseTranscript(slice).events);
}

