import test from 'node:test';
import assert from 'node:assert/strict';
import { parseDshHook } from '../src/dsh/parse-hook.js';

function payload(hook, extra = {}) {
  return Buffer.from(
    JSON.stringify({
      hook_type: hook.replace(/-/g, '_'),
      session_id: 'session-1',
      timestamp: '2026-01-13T12:00:00Z',
      raw_data: { dsh: {} },
      ...extra
    })
  );
}

test('maps every declared hook to its event type', () => {
  const expected = {
    'session-start': 1,
    'turn-start': 2,
    'turn-end': 3,
    compaction: 4,
    'session-end': 5,
    'subagent-start': 6,
    'subagent-end': 7
  };
  for (const [hook, type] of Object.entries(expected)) {
    const event = parseDshHook(hook, payload(hook));
    assert.equal(event.type, type, hook);
    assert.equal(event.session_id, 'session-1');
    assert.equal(event.timestamp, '2026-01-13T12:00:00Z');
  }
});

test('carries the prompt and model through', () => {
  const event = parseDshHook(
    'turn-start',
    payload('turn-start', { user_prompt: 'Fix the bug', raw_data: { dsh: { model: 'deepseek-flash' } } })
  );
  assert.equal(event.prompt, 'Fix the bug');
  assert.equal(event.model, 'deepseek-flash');
});

test('returns null for unknown hooks, invalid JSON and missing session ids', () => {
  assert.equal(parseDshHook('pre-tool-use', payload('pre-tool-use')), null);
  assert.equal(parseDshHook('turn-start', Buffer.from('not json')), null);
  assert.equal(parseDshHook('turn-start', Buffer.from(JSON.stringify({ hook_type: 'turn_start' }))), null);
});
