import test from 'node:test';
import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const BIN = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'bin', 'entire-agent-dsh');

function run(args, input) {
  return new Promise((resolve, reject) => {
    const child = execFile(process.execPath, [BIN, ...args], { timeout: 20000 }, (error, stdout, stderr) => {
      if (error) reject(new Error(stderr || error.message));
      else resolve({ stdout, stderr });
    });
    if (input !== undefined) child.stdin.end(typeof input === 'string' ? input : JSON.stringify(input));
    else child.stdin.end();
  });
}

test('info declares hooks and transcript capabilities', async () => {
  const { stdout } = await run(['info']);
  const info = JSON.parse(stdout);
  assert.equal(info.protocol_version, 1);
  assert.equal(info.name, 'dsh');
  assert.equal(info.capabilities.hooks, true);
  assert.equal(info.capabilities.transcript_analyzer, true);
  assert.ok(info.hook_names.includes('turn-end'));
});

test('detect reports presence', async () => {
  const { stdout } = await run(['detect']);
  assert.equal(typeof JSON.parse(stdout).present, 'boolean');
});

test('parse-hook normalizes a turn-end payload', async () => {
  const { stdout } = await run(
    ['parse-hook', '--hook', 'turn-end'],
    { session_id: 'session-1', timestamp: '2026-01-13T12:00:00Z', raw_data: { dsh: {} } }
  );
  const event = JSON.parse(stdout);
  assert.equal(event.type, 3);
  assert.equal(event.session_id, 'session-1');
});

test('parse-hook prints null for an unknown hook', async () => {
  const { stdout } = await run(['parse-hook', '--hook', 'unknown'], { session_id: 'session-1' });
  assert.equal(stdout.trim(), 'null');
});

test('get-session-id echoes the hook input id', async () => {
  const { stdout } = await run(['get-session-id'], { session_id: 'abc' });
  assert.deepEqual(JSON.parse(stdout), { session_id: 'abc' });
});

