}", "new_string": "export function sessionFileFor(sessionId, repoPath) {
  return resolveSessionFile(findSessionDir(repoPath), sessionId);
}

/**
 * Locate a session file by session id alone.
 *
 * `sessionFileFor` assumes the session belongs to the repository's workspace,
 * but a DSH session records the directory it was *launched* in (`header.cwd`),
 * which is often a parent folder rather than the repository the user works in
 * — this session runs in $HOME and the repository is a subdirectory. In that
 * case the slug for ENTIRE_REPO_ROOT holds no session directory at all.
 *
 * So walk the session root newest-first and compare the header id, which is
 * exact. The activity scan is a fallback for pathological session counts.
 */
export function findSessionFileById(sessionId, root = sessionsRoot()) {
  if (typeof sessionId !== 'string' || sessionId === '') return null;
  if (!isDirectory(root)) return null;

  const candidates = [];
  for (const workspaceEntry of fs.readdirSync(root)) {
    const workspaceDir = path.join(root, workspaceEntry);
    if (!isDirectory(workspaceDir)) continue;
    for (const entry of fs.readdirSync(workspaceDir)) {
      const sessionDir = path.join(workspaceDir, entry);
      if (!isDirectory(sessionDir)) continue;
      const file = firstSessionFile(sessionDir);
      if (file === null) continue;
      if (entry === sessionId) return file;
      try {
        candidates.push({ file, mtime: fs.statSync(file).mtimeMs });
      } catch {
        // A session that vanished mid-scan is simply not a candidate.
      }
    }
  }

  candidates.sort((a, b) => b.mtime - a.mtime);
  for (const { file } of candidates) {
    const header = readSessionHeader(file);
    if (header !== null && header.id === sessionId) return file;
  }
  return null;
}

/**
 * Resolve the session file for a hook event: try the workspace slug for the
 * repository (the common layout), then fall back to an id scan.
 *
 * @returns {string} the session file, or '' when it cannot be found.
 */
export function resolveSessionFileOrHome(sessionId, repoPath) {
  try {
    return sessionFileFor(sessionId, repoPath);
  } catch {
    // The session was launched from a different (parent) directory.
  }
  return findSessionFileById(sessionId) ?? '';
}"}

