#!/usr/bin/env node
/**
 * Install the entire-agent-dsh launcher on PATH.
 *
 * The protocol binary is a Node module invoked through a shebang, so whatever
 * spawns it must resolve `node`. Agent hosts do not always run with an
 * interactive shell's PATH, so this installer writes a /bin/sh launcher that
 * pins the Node executable that installed it.
 *
 * usage: node scripts/install.mjs [--dest <dir>]
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const packageRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const args = process.argv.slice(2);
let destDir = path.join(os.homedir(), '.local', 'bin');
for (let i = 0; i < args.length; i += 1) {
  if (args[i] === '--dest' && args[i + 1] !== undefined) {
    destDir = args[i + 1];
    i += 1;
  }
}

function shellQuote(value) {
  return "'" + String(value).replace(/'/g, "'\\''") + "'";
}

const target = path.join(packageRoot, 'bin', 'entire-agent-dsh');
const launcher = path.join(destDir, 'entire-agent-dsh');
fs.mkdirSync(destDir, { recursive: true });
fs.rmSync(launcher, { force: true });
const script =
  '#!/bin/sh\n' +
  '# Generated by entire-agent-dsh/scripts/install.mjs; re-run it after moving the package or changing node.\n' +
  'exec ' + shellQuote(process.execPath) + ' ' + shellQuote(target) + ' "$@"\n';
fs.writeFileSync(launcher, script);
fs.chmodSync(launcher, 0o755);
console.log('installed ' + launcher);
console.log('  node: ' + process.execPath);
console.log('  bin:  ' + target);
